'use strict';
const CONFIG={
  supabaseUrl:'https://ccboibbhsztcupfcrndx.supabase.co',
  publishableKey:'sb_publishable_Dzt9mbx7jw9qYEEJn7NAdg_zp7DPrJ9',
  mailFunction:'wapilot-microsoft-mail',calendarFunction:'wapilot-google-calendar'
};
const $=id=>document.getElementById(id);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const fmt=d=>d?new Date(d).toLocaleDateString('fr-BE',{day:'2-digit',month:'short'}):'';
const nowISO=()=>new Date().toISOString();
const today=()=>new Date().toISOString().slice(0,10);
const state={db:null,user:null,profile:null,page:'home',view:'',context:'',copros:[],allowed:new Set(),tasks:[],sinistres:[],notes:[],events:[],mailboxes:[],mailbox:'',mails:[],selectedMail:null,mailError:'',calendarError:'',moduleRows:[],moduleKey:'',moduleError:'',dataErrors:[],updated:0,filter:'open',mailFolder:'inbox',mailFolders:[],mailFilter:'all',mailQuery:'',mailNext:null,mailLoading:false,mailListSeq:0,mailAttachments:[],captureFiles:[],capturePreviewUrls:[],cameraStream:null,uploadBusy:false,pendingCapture:null,busy:false};
let bannerTimer=0;
function toast(message){const t=$('toast');t.textContent=message;t.classList.remove('hidden');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>t.classList.add('hidden'),4300)}
function info(text,warning=false){const b=$('banner');b.textContent=text;b.style.background=warning?'#fff3e9':'#e8f7f1';b.classList.toggle('hidden',!text)}
function msg(e){return e?.message||String(e||'Erreur inconnue')}
function setBusy(yes){state.busy=yes;document.querySelectorAll('.submit-button').forEach(x=>x.disabled=yes)}
function dateKey(s){if(!s)return '';const m=String(s).match(/^(\d{4})-(\d\d)-(\d\d)/);return m?m[0]:''}
function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/^\[[^\]]+\]\s*/,'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function taskCopro(t){const id=String(t.copro_id||'');const name=String(t.copro||'');if(id){const byId=state.copros.find(c=>String(c.id||'')===id||String(c.canonical_id||'')===id);if(byId)return byId}if(!name)return null;const matches=state.copros.filter(c=>norm(name)===norm(c.name)||name===String(c.code));return matches.length===1?matches[0]:null}
function canSeeCopro(c){return !!c&&state.allowed.has(String(c.code))}
function allowedTask(t){return canSeeCopro(taskCopro(t))}
function scopedTasks(){return state.tasks.filter(t=>allowedTask(t)&&(!state.context||taskCopro(t)?.name===state.context))}
function scopedSinistres(){return state.sinistres.filter(s=>{if(state.context&&norm(s.copro)!==norm(state.context))return false;const hits=state.copros.filter(c=>norm(c.name)===norm(s.copro));return hits.length===1&&canSeeCopro(hits[0])})}
function openTasks(){return scopedTasks().filter(t=>!['done','completed','archived','closed','cancelled'].includes(String(t.status||'').toLowerCase()))}
function iconEmpty(label){return `<div class="empty">${safe(label)}</div>`}
function refreshContext(){const c=$('context');c.classList.toggle('hidden',!state.context);$('context-name').textContent=state.context?'▦ '+state.context:''}
function pickContext(name){const c=state.copros.find(x=>x.name===name);if(!c||!canSeeCopro(c)){toast('Résidence non autorisée.');return}state.context=name;refreshContext();nav('copros');render()}
function resetContext(){state.context='';refreshContext();render()}
function nav(page){state.page=page;state.view='';document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('main').scrollTop=0;render();if(page==='mails'&&!state.mailboxes.length)loadMailboxes();if(page==='home'&&!state.events.length)loadCalendar()}
function section(head,body,link){return `<section class="section"><div class="section-title"><h2>${safe(head)}</h2>${link||''}</div>${body}</section>`}
function taskRow(t){const c=taskCopro(t);const urgent=['high','critical'].includes(t.priority)||t.is_urgent;return `<div class="card row-card"><div class="row-main"><b>${safe(t.title)}</b><small>${safe(c?.name||t.copro||'Sans résidence')} · ${t.due_date?'Échéance '+safe(fmt(t.due_date)):'Sans échéance'}</small></div><span class="tag ${urgent?'hot':''}">${urgent?'Urgent':safe(t.status||'À faire')}</span><button class="row-action" data-task="${safe(t.id)}" aria-label="Détail">›</button></div>`}
function renderHome(){const open=openTasks(),urgent=open.filter(t=>t.is_urgent||['high','critical'].includes(t.priority));const todayEvents=state.events.filter(e=>dateKey(e.start?.dateTime||e.start?.date)===today());const tech=open.filter(t=>{let h=t.history;try{if(typeof h==='string')h=JSON.parse(h)}catch{}return Array.isArray(h)&&h.some(x=>x?.source==='dl_technik'||x?.dl_technik_visit_id||x?.integration==='dl_technik')});return `<div class="eyebrow">VOTRE ESPACE MOBILE</div><div class="section-title"><h1>Bonjour ${safe((state.profile?.full_name||state.user?.email||'').split(' ')[0])}</h1><span class="tag ok">En ligne</span></div><p class="sub">${new Date().toLocaleDateString('fr-BE',{weekday:'long',day:'numeric',month:'long'})} · Données WAPILOT</p>
<div class="stats"><div class="card stat"><div class="symbol">▦ <strong>${todayEvents.length}</strong></div><span>Rendez-vous</span><small>Aujourd'hui</small></div><div class="card stat"><div class="symbol">☑ <strong>${open.length}</strong></div><span>Tâches ouvertes</span><small>Résidences autorisées</small></div><div class="card stat"><div class="symbol">! <strong>${urgent.length}</strong></div><span>Urgences</span><small>Priorité élevée</small></div><div class="card stat"><div class="symbol">♨ <strong>${tech.length}</strong></div><span>Signalements</span><small>DL TECHNIK détectés</small></div></div>
${section('Aujourd’hui',todayEvents.length?todayEvents.slice(0,4).map(e=>`<div class="card row-card"><span class="tag">${safe(new Date(e.start?.dateTime||e.start?.date).toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'}))}</span><div class="row-main"><b>${safe(e.summary||'Rendez-vous')}</b><small>${safe(e.location||'Agenda Google')}</small></div></div>`).join(''):(state.calendarError?iconEmpty('Agenda non disponible : '+state.calendarError):iconEmpty('Aucun rendez-vous chargé pour aujourd’hui')))}
${section('Priorités',urgent.slice(0,5).map(taskRow).join('')||iconEmpty('Aucune tâche urgente'))}
${section('Actions rapides',`<div class="two"><button class="quick" data-go="capture"><span>◎</span>Note / photo terrain</button><button class="quick" data-open-create="1"><span>＋</span>Créer une tâche</button><button class="quick" data-go="mails"><span>✉</span>Consulter les mails</button><button class="quick" data-go="copros"><span>▦</span>Fiche résidence</button></div>`)}<p class="footer-note">Les comptages concernent les enregistrements chargés et autorisés. Actualisez pour rafraîchir les informations.</p>`}
function renderTasks(){const rows=state.filter==='done'?scopedTasks().filter(t=>['done','completed','archived','closed'].includes(String(t.status).toLowerCase())):openTasks();return `<div class="section-title"><h1>Tâches</h1><button data-open-create="1">＋ Nouvelle</button></div><p class="sub">Tâches WAPILOT des résidences auxquelles vous avez accès.</p><div class="chips"><button data-filter="open" class="${state.filter==='open'?'selected':''}">À traiter (${openTasks().length})</button><button data-filter="done" class="${state.filter==='done'?'selected':''}">Clôturées</button></div><div class="stack">${rows.slice(0,140).map(taskRow).join('')||iconEmpty('Aucune tâche dans cette catégorie')}</div>`}
function renderCopros(){const list=state.copros.filter(c=>canSeeCopro(c)&&(!state.context||c.name===state.context));return `<div class="section-title"><h1>Mes copropriétés</h1><span class="tag">${list.length}</span></div><div class="searchbox">⌕ <input id="copro-search" aria-label="Chercher une résidence" placeholder="Rechercher une résidence" autocomplete="off"></div><div id="copro-results" class="stack" style="margin-top:12px">${coproListHtml(list)}</div>`}
function coproListHtml(arr){return arr.slice(0,250).map(c=>`<div class="card row-card"><div class="row-main"><b>${safe(c.name||c.code)}</b><small>${safe(c.profile?.address||'')} ${safe(c.profile?.city||'')}</small></div><button class="row-action" data-copro="${safe(c.code)}">›</button></div>`).join('')||iconEmpty('Aucune résidence accessible')}
function renderCoproDetail(c){const ts=state.tasks.filter(t=>taskCopro(t)?.code===c.code),si=state.sinistres.filter(s=>norm(s.copro)===norm(c.name));const ad=[c.profile?.address,c.profile?.postal_code,c.profile?.city].filter(Boolean).join(', ');return `<button class="link" data-back="copros">← Copropriétés</button><div class="eyebrow">FICHE COPROPRIÉTÉ</div><div class="detail"><h2>${safe(c.name)}</h2><p class="sub">${safe(ad||'Adresse non renseignée')}</p><div class="card pad"><div class="detail-line"><span>Code interne</span><b>${safe(c.code)}</b></div><div class="detail-line"><span>N° BCE</span><b>${safe(c.profile?.bce||c.profile?.enterprise_number||'—')}</b></div><div class="detail-line"><span>Tâches chargées</span><b>${ts.length}</b></div><div class="detail-line"><span>Sinistres chargés</span><b>${si.length}</b></div></div><div class="section"><div class="section-title"><h2>Accès rapides</h2></div><div class="two"><button class="quick" data-copro-action="tasks" data-code="${safe(c.code)}"><span>☷</span>Tâches</button><button class="quick" data-copro-action="sinistres" data-code="${safe(c.code)}"><span>♨</span>Sinistres</button><button class="quick" data-copro-action="capture" data-code="${safe(c.code)}"><span>◎</span>Note terrain</button><button class="quick" data-copro-action="mails" data-code="${safe(c.code)}"><span>✉</span>Mails</button><button class="quick" data-module="fire" data-code="${safe(c.code)}"><span>♨</span>Incendie</button><button class="quick" data-module="lifts" data-code="${safe(c.code)}"><span>↕</span>Ascenseurs</button><button class="quick" data-module="notary" data-code="${safe(c.code)}"><span>✒</span>Mutations</button><button class="quick" data-module="ag" data-code="${safe(c.code)}"><span>▤</span>Assemblées générales</button><button class="quick" data-module="technik" data-code="${safe(c.code)}"><span>⚒</span>DL TECHNIK</button></div></div>${section('Dernières tâches',ts.slice(0,5).map(taskRow).join('')||iconEmpty('Aucune tâche chargée'))}</div>`}
function renderSinistres(){const rows=scopedSinistres();return `<button class="link" data-back="copros">← Retour aux copropriétés</button><div class="section-title"><h1>Sinistres</h1><span class="tag">${rows.length}</span></div><p class="sub">Consultation des dossiers actuellement accessibles.</p>${rows.slice(0,80).map(s=>`<div class="card row-card"><div class="row-main"><b>${safe(s.type||s.title||s.description||'Sinistre')}</b><small>${safe(s.copro||'')} · ${safe(fmt(s.date_sinistre))}</small></div><button class="row-action" data-sinistre="${safe(s.id)}">›</button></div>`).join('')||iconEmpty('Aucun sinistre accessible')}`}
function renderSinistreDetail(s){return `<button class="link" data-go="sinistres">← Sinistres</button><div class="detail"><h2>${safe(s.type||s.title||'Sinistre')}</h2><p class="sub">${safe(s.copro)} · ${safe(fmt(s.date_sinistre))}</p><div class="card pad"><div class="detail-line"><span>Statut</span><b>${safe(s.status)}</b></div><div class="detail-line"><span>Référence</span><b>${safe(s.numero_dossier||s.reference||s.id)}</b></div></div><div class="section"><h3>Description</h3><p>${safe(s.description||s.circonstances||'Aucune description')}</p></div></div>`}
function mailPerson(m){const p=m.from?.emailAddress||m.sender?.emailAddress||{};return {name:p.name||p.address||'Expéditeur',email:p.address||''}}
function mailTime(m){const d=new Date(m.receivedDateTime||m.sentDateTime||Date.now());return Number.isFinite(d.getTime())?d.toLocaleDateString('fr-BE',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):''}
function mailRow(m,i){const who=mailPerson(m);const initials=who.name.split(/\s+/).map(w=>w[0]||'').slice(0,2).join('').toUpperCase();return `<button class="outlook-item ${m.isRead?'':'unread'}" data-mail="${i}" aria-label="Ouvrir : ${safe(m.subject||'sans objet')}"><span class="mail-avatar">${safe(initials||'@')}</span><span class="outlook-lines"><span class="mail-fromline"><strong>${safe(who.name)}</strong><time>${safe(mailTime(m))}</time></span><b class="mail-subject">${safe(m.subject||'(sans objet)')}</b><span class="mail-snippet">${safe(m.bodyPreview||'').slice(0,130)}</span></span><span class="mail-indicators">${m.hasAttachments?'📎':''} ${m.importance==='high'?'❗':''} ${!m.isRead?'<span class="unread-dot"></span>':''}</span></button>`}
function renderMails(){const folders=[['inbox','Réception'],['sent','Envoyés'],['draft','Brouillons'],['archive','Archives'],['trash','Corbeille']];const unread=state.mailFilter==='unread';return `<div class="mail-toolbar"><div class="section-title"><h1>Messagerie</h1><button class="mail-compose-btn" data-compose="1">✎ Nouveau</button></div><div class="mail-account"><span>Microsoft 365</span><select id="mailbox-select" aria-label="Boîte mail">${state.mailboxes.map(m=>`<option value="${safe(m.email)}" ${m.email===state.mailbox?'selected':''}>${safe(m.name||m.email)}</option>`).join('')||'<option value="">Chargement…</option>'}</select></div><div class="mail-search"><span>⌕</span><input id="mail-search-input" placeholder="Rechercher dans Outlook" value="${safe(state.mailQuery)}" autocomplete="off"><button id="mail-search-submit" aria-label="Rechercher">Rechercher</button></div><div class="folder-chips">${folders.map(([k,v])=>`<button data-mail-folder="${k}" class="${state.mailFolder===k&&!state.mailQuery?'active':''}">${v}</button>`).join('')}<button data-mail-folder="folders">Dossiers ▾</button></div><div class="mail-filter-row"><button class="${!unread?'active':''}" data-mail-filter="all">Tous</button><button class="${unread?'active':''}" data-mail-filter="unread">Non lus</button><button id="mail-reload" aria-label="Actualiser">↻</button></div></div>${state.mailError?`<div class="danger-note">${safe(state.mailError)}</div>`:''}<div class="mail-list">${state.mailLoading&&state.mails.length===0?'<div class="loading">Chargement des messages…</div>':state.mails.map(mailRow).join('')||iconEmpty('Aucun message dans ce dossier')}${state.mailNext?'<button class="secondary wide more-mails" id="mail-more" type="button">Charger plus de messages</button>':''}</div>`}
function renderMailDetail(m){const from=mailPerson(m);const to=(m.toRecipients||[]).map(x=>x.emailAddress?.address).filter(Boolean).join('; ');const cc=(m.ccRecipients||[]).map(x=>x.emailAddress?.address).filter(Boolean).join('; ');const att=state.mailAttachments||[];return `<div class="mail-detail"><button class="mail-back" data-go="mails">← <span>Courrier</span></button><h2>${safe(m.subject||'(sans objet)')}</h2><div class="mail-message-meta"><span class="mail-avatar">${safe((from.name[0]||'@').toUpperCase())}</span><div><b>${safe(from.name)}</b><small>${safe(from.email)}</small><small>À : ${safe(to||'—')}${cc?' · Cc : '+safe(cc):''}</small><small>${safe(mailTime(m))}</small></div></div><div class="mail-detail-actions"><button data-mail-action="reply">↩ Répondre</button><button data-mail-action="replyall">↩ Tous</button><button data-mail-action="forward">⇢ Transférer</button></div><div class="mail-body">${safe(plain(m.body?.content||m.bodyPreview||'Contenu indisponible'))}</div>${att.length?`<div class="section"><b>Pièces jointes (${att.length})</b><div class="stack">${att.filter(x=>!x.isInline).map((x,i)=>`<button class="mail-att" data-mail-attachment="${safe(x.id)}"><span>📎</span><span>${safe(x.name)}<small>${Math.ceil((x.size||0)/1024)} Ko</small></span><span>↓</span></button>`).join('')}</div></div>`:''}<div class="mail-detail-bottom"><button class="secondary" data-mail-action="toggle-read">${m.isRead?'Marquer non lu':'Marquer lu'}</button><button class="secondary" data-mail-action="move">Déplacer</button><button class="secondary" data-mail-action="archive">Archiver</button><button class="secondary danger" data-mail-action="delete">Supprimer</button></div></div>`}
function renderCapture(){return `<div class="section-title"><h1>Capture rapide</h1><span class="pill">Terrain</span></div><p class="sub">Photos et remarques envoyées <b>directement à WAPILOT</b> à l’enregistrement. Connexion requise.</p><div class="card pad"><label>Copropriété</label><select id="note-copro"><option value="">Sans résidence</option>${state.copros.filter(canSeeCopro).map(c=>`<option value="${safe(c.code)}" ${c.name===state.context?'selected':''}>${safe(c.name)}</option>`).join('')}</select><label>Note terrain<textarea id="note-text" placeholder="Ex. : ampoule à remplacer au 2e étage…"></textarea></label><div class="capture-tiles"><button type="button" id="camera-btn"><span>◎</span>Prendre une photo</button><button type="button" id="file-btn"><span>▧</span>Choisir des photos</button></div><input type="file" id="camera-input" accept="image/*" capture="environment" style="position:absolute;left:-9999px;width:1px;height:1px;opacity:0"><input type="file" id="file-input" accept="image/*" multiple style="position:absolute;left:-9999px;width:1px;height:1px;opacity:0"><div class="photo-preview" id="photos-preview"></div><label><input type="checkbox" id="note-urgent" style="width:auto;min-height:auto"> Signalement urgent</label><button type="button" id="save-note" class="primary wide submit-button">Envoyer à WAPILOT</button><p id="capture-status" class="footer-note" role="status">Rien n’est conservé dans une file d’attente. En cas d’échec, la saisie reste à l’écran pour réessayer.</p></div>${section('Dernières notes envoyées',state.notes.slice(0,8).map(n=>`<div class="card pad" style="margin-bottom:9px"><b>${safe(n.text||'Photo terrain').slice(0,100)}</b><small style="display:block;margin-top:6px;color:var(--muted)">${safe(n.copro_name||'Sans résidence')} · ${safe(fmt(n.created_at))}</small></div>`).join('')||iconEmpty('Aucune note envoyée'))}`}
function renderLocalCaptureRows(){return ''}

const MODULES={fire:{label:'Prévention incendie',table:'wp_fire_cases'},lifts:{label:'Ascenseurs',table:'wp_lifts'},notary:{label:'Mutations',table:'web_notaire_requests'},ag:{label:'Assemblées générales',table:'web_ags'},technik:{label:'DL TECHNIK',table:'technik_v_interventions'}};
async function openCoproModule(key,code){const c=state.copros.find(x=>String(x.code)===String(code));if(!c||!canSeeCopro(c)||!MODULES[key])return;state.context=c.name;refreshContext();state.moduleKey=key;state.moduleRows=[];state.moduleError='';state.page='copros';state.view='module';render();try{let q=state.db.from(MODULES[key].table).select('*').limit(300);if(['fire','lifts'].includes(key))q=q.eq('copro_code',code);if(['ag','notary'].includes(key))q=q.eq('copro',c.name);if(key==='technik'){if(!c.canonical_id&&!c.id)throw Error('Identifiant de copropriété absent');q=q.eq('copro_id',c.canonical_id||c.id)}const {data,error}=await q;if(error)throw error;state.moduleRows=data||[]}catch(e){state.moduleError=msg(e)}if(state.view==='module')render()}
function renderModule(){const c=state.copros.find(x=>x.name===state.context),config=MODULES[state.moduleKey];const body=state.moduleError?`<div class="danger-note">${safe(state.moduleError)}</div>`:state.moduleRows.length?state.moduleRows.map(x=>`<div class="card pad" style="margin:9px 0"><b>${safe(x.title||x.name||x.subject||x.intervention_type_code||config.label)}</b><p class="sub">${safe(x.status||x.last_verdict||x.lift_name||'')} · ${safe(fmt(x.created_at||x.planned_date||x.last_report_date))}</p><small class="muted">${safe(x.description||x.address||'')}</small></div>`).join(''):iconEmpty('Aucun élément chargé dans cette rubrique');return `<button class="link" data-copro="${safe(c?.code||'')}">← Fiche copropriété</button><div class="section-title"><h1>${safe(config.label)}</h1></div><p class="sub">${safe(c?.name||'')} · Consultation des enregistrements existants</p>${body}<p class="footer-note">Module consultable en lecture. Les modifications avancées restent disponibles dans WAPILOT sur ordinateur.</p>`}
function render(){if(!state.user)return;const p=state.page;const view=state.view;
if(view==='module'){$('main').innerHTML=renderModule();return}
if(view.startsWith('copro:')){const c=state.copros.find(x=>x.code===view.slice(6));$('main').innerHTML=c&&canSeeCopro(c)?renderCoproDetail(c):iconEmpty('Copropriété non accessible');return}
if(view.startsWith('sinistre:')){const s=scopedSinistres().find(x=>String(x.id)===view.slice(9));$('main').innerHTML=s?renderSinistreDetail(s):iconEmpty('Sinistre non accessible');return}
if(view==='sinistres'){$('main').innerHTML=renderSinistres();return}
if(view==='mail'){$('main').innerHTML=state.selectedMail?renderMailDetail(state.selectedMail):renderMails();return}
switch(p){case 'home':$('main').innerHTML=renderHome();break;case 'tasks':$('main').innerHTML=renderTasks();break;case 'copros':$('main').innerHTML=renderCopros();break;case 'capture':$('main').innerHTML=renderCapture();break;case 'mails':$('main').innerHTML=renderMails();break;default:$('main').innerHTML=renderHome()}}
function modal(title,html,callback){$('modal-root').innerHTML=`<div class="overlay"><div class="sheet"><div class="sheet-head"><h2>${safe(title)}</h2><button id="close-modal" aria-label="Fermer">×</button></div>${html}</div></div>`;const overlay=$('modal-root').firstElementChild;overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.id==='close-modal')closeModal()});if(callback)callback(overlay)}
function closeModal(){cameraStop();$('modal-root').innerHTML=''}
function openTask(t){const c=taskCopro(t);modal('Détail de la tâche',`<div class="detail"><h2>${safe(t.title)}</h2><p class="sub">${safe(c?.name||t.copro||'')} · ${safe(t.priority||'normal')}</p><div class="card pad"><div class="detail-line"><span>Statut</span><b>${safe(t.status)}</b></div><div class="detail-line"><span>Échéance</span><b>${safe(t.due_date||'Non définie')}</b></div></div><div class="actions"><button class="secondary" id="cancel-task">Fermer</button><button class="primary" id="task-inprogress">En cours</button></div></div>`,r=>{r.querySelector('#cancel-task').onclick=closeModal;r.querySelector('#task-inprogress').onclick=async()=>{if(!confirm('Passer cette tâche au statut En cours ?'))return;try{const {error}=await state.db.from('web_tasks_new').update({status:'inprogress'}).eq('id',t.id);if(error)throw error;t.status='inprogress';closeModal();render();toast('Tâche mise à jour')}catch(e){toast('Modification refusée : '+msg(e))}}})}
function taskForm(){const options=state.copros.filter(canSeeCopro).map(c=>`<option value="${safe(c.code)}" ${c.name===state.context?'selected':''}>${safe(c.name)}</option>`).join('');modal('Nouvelle tâche',`<form id="task-form"><label>Résidence<select name="copro" required><option value="">Choisir une copropriété</option>${options}</select></label><label>Objet<input name="title" maxlength="250" required placeholder="Ex. : remplacer une ampoule"></label><label>Priorité<select name="priority"><option value="normal">Normale</option><option value="high">Urgente</option><option value="low">Faible</option></select></label><label>Échéance<input name="due" type="date"></label><div class="actions"><button type="button" class="secondary" id="cancel-create">Annuler</button><button type="submit" class="primary submit-button">Créer dans WAPILOT</button></div><p class="footer-note">La création nécessite une confirmation Supabase ; aucune tâche fictive n'est affichée comme enregistrée.</p></form>`,el=>{el.querySelector('#cancel-create').onclick=closeModal;el.querySelector('#task-form').onsubmit=createTask})}
async function createTask(e){e.preventDefault();if(state.busy)return;const form=new FormData(e.currentTarget);const c=state.copros.find(x=>x.code===form.get('copro'));if(!c||!canSeeCopro(c))return toast('Copropriété non autorisée');const title=String(form.get('title')||'').trim();if(!title)return;const pri=form.get('priority');const assigned=state.user.id;const now=new Date().toLocaleDateString('fr-FR');const record={id:Date.now(),copro:c.name,copro_id:c.canonical_id||c.id||null,due_date:form.get('due')||null,waiting_response:false,priority_level:({low:1,normal:2,high:3,critical:4}[pri]||2),title,status:'todo',priority:pri,date:now,is_extra_cost:false,is_ag_point:false,is_urgent:pri==='high',is_billed:false,created_by:state.user.id,assigned_to:assigned,history:JSON.stringify([{date:now,text:'Tâche créée depuis WAPI POCKET 2.0',author:state.profile.full_name||state.user.email,workflow:{next_action:title,due_date:form.get('due')||'',priority:pri}}])};setBusy(true);try{let {error}=await state.db.from('web_tasks_new').insert(record);if(error)throw error;closeModal();toast('Tâche créée dans WAPILOT');await loadTasks();render()}catch(e){toast('Tâche non créée : '+msg(e))}finally{setBusy(false)}}
function emailSafeHTML(text){return safe(text).replace(/\r?\n/g,'<br>')}
let composeSource=null;
function composeForm(to='',subject='',mode='send',source=null){composeSource=source||null;const ccDefault=mode==='replyall'?(source?.ccRecipients||[]).map(x=>x.emailAddress?.address).filter(x=>x&&x.toLowerCase()!==state.mailbox.toLowerCase()).join('; '):'';const values={send:'Nouveau message',reply:'Répondre',replyall:'Répondre à tous',forward:'Transférer',draft:'Enregistrer un brouillon'};modal(values[mode]||'Message',`<form id="compose-form"><input type="hidden" name="mode" value="${safe(mode)}"><label>De<select name="mailbox">${state.mailboxes.map(x=>`<option value="${safe(x.email)}" ${x.email===state.mailbox?'selected':''}>${safe(x.name||x.email)}</option>`).join('')}</select></label><label>À<input type="text" name="to" value="${safe(to)}" placeholder="adresse@exemple.be"></label><details class="mail-cc"><summary>Cc / Cci</summary><label>Cc<input name="cc" value="${safe(ccDefault)}" placeholder="Copie"></label><label>Cci<input name="bcc" placeholder="Copie cachée"></label></details><label>Objet<input name="subject" value="${safe(subject)}" required></label><label>Message<textarea name="body" rows="9" required placeholder="Votre message…"></textarea></label><label>Pièces jointes<input name="attachments" type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx,.txt,.zip"></label><p class="footer-note">Les pièces jointes sont envoyées via la fonction Microsoft 365 existante (taille totale conseillée : moins de 3 Mo). Le brouillon n'envoie aucun message.</p><div class="actions"><button type="button" class="secondary" id="compose-cancel">Annuler</button><button type="submit" class="secondary submit-button" id="compose-draft">Brouillon</button><button type="submit" class="primary submit-button" id="compose-send">Envoyer</button></div></form>`,el=>{el.querySelector('#compose-cancel').onclick=closeModal;el.querySelector('#compose-form').addEventListener('submit',sendMail);el.querySelector('#compose-draft').addEventListener('click',()=>{el.querySelector('#compose-form').dataset.saveDraft='true'});el.querySelector('#compose-send').addEventListener('click',()=>{el.querySelector('#compose-form').dataset.saveDraft='false'})})}
async function base64File(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})}
function mailAddresses(s){return String(s||'').split(/[;,]+/).map(x=>x.trim()).filter(Boolean)}
function validAddresses(s){return mailAddresses(s).every(x=>/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(x))}
async function sendMail(e){e.preventDefault();if(state.busy)return;const f=new FormData(e.currentTarget);const form=e.currentTarget,saveDraft=form.dataset.saveDraft==='true';const to=String(f.get('to')||'').trim(),cc=String(f.get('cc')||''),bcc=String(f.get('bcc')||'');const mode=String(f.get('mode')||'send');if(!validAddresses(to)||!validAddresses(cc)||!validAddresses(bcc)){toast('Adresse e-mail invalide');return}if(!saveDraft&&mode!=='reply'&&mode!=='replyall'&&!to){toast('Saisis un destinataire');return}if(!saveDraft&&!confirm(`Confirmer l’envoi Microsoft 365 depuis ${f.get('mailbox')} ?`))return;const files=[...form.querySelector('input[name=attachments]').files];if(files.reduce((n,x)=>n+x.size,0)>3*1024*1024){toast('Pièces jointes trop volumineuses (3 Mo maximum)');return}setBusy(true);try{const attachments=await Promise.all(files.map(async x=>({name:x.name,contentType:x.type||'application/octet-stream',contentBytes:await base64File(x)})));const body={action:saveDraft?'draft':mode,mailbox:f.get('mailbox'),to,cc,bcc,subject:f.get('subject'),body_html:emailSafeHTML(String(f.get('body'))),attachments};if(!saveDraft&&['reply','replyall','forward'].includes(mode)){if(!composeSource?.id)throw Error('Message original introuvable');body.message_id=composeSource.id}else if(!saveDraft)body.action='send';const r=await invoke(CONFIG.mailFunction,body);if(r?.ok!==true)throw Error('Aucune confirmation de Microsoft 365');closeModal();toast(saveDraft?'Brouillon enregistré dans Microsoft 365':'Message envoyé via Microsoft 365');await loadMails()}catch(e){toast('Opération non confirmée : '+msg(e))}finally{setBusy(false)}}
async function mailAction(action){const m=state.selectedMail;if(!m||state.busy)return;const source={...m};if(['reply','replyall','forward'].includes(action)){const from=mailPerson(m).email;let to=action==='reply'?from:action==='replyall'?[from,...(m.toRecipients||[]).map(x=>x.emailAddress?.address).filter(x=>x&&x.toLowerCase()!==state.mailbox.toLowerCase())].filter(Boolean).join('; '):'';const subj=action==='forward'?('TR : '+(m.subject||'')):('RE : '+(m.subject||''));composeForm(to,subj,action,source);return}if(action==='move'){await loadMailFolders();const options=[['inbox','Réception'],['sent','Envoyés'],['archive','Archives'],['trash','Corbeille'],...state.mailFolders.filter(f=>!f.isHidden).map(f=>[f.id,f.displayName])];modal('Déplacer le message',`<label>Dossier de destination<select id="move-destination">${options.map(([id,n])=>`<option value="${safe(id)}">${safe(n)}</option>`).join('')}</select></label><button class="primary wide" id="confirm-move">Déplacer</button>`,()=>{$('confirm-move').onclick=async()=>{const dest=$('move-destination').value;closeModal();await mailActionMutation('move',{destination:dest},source)}});return}if(action==='delete'&&!confirm('Supprimer ce message de la boîte Microsoft 365 ?'))return;if(action==='archive')return mailActionMutation('move',{destination:'archive'},source);if(action==='delete')return mailActionMutation('delete',{},source);if(action==='toggle-read')return mailActionMutation('mark_read',{is_read:!m.isRead},source)}
async function mailActionMutation(action,extra,m){if(state.busy)return;setBusy(true);try{const response=await invoke(CONFIG.mailFunction,{action,mailbox:state.mailbox,message_id:m.id,...extra});if(response?.ok!==true)throw Error('Action non confirmée');if(action==='mark_read'){m.isRead=extra.is_read;state.selectedMail={...m};render()}else{state.view='';state.selectedMail=null;await loadMails()}toast('Action enregistrée dans Microsoft 365')}catch(e){toast('Action refusée : '+msg(e))}finally{setBusy(false)}}
async function downloadMailAttachment(id){const m=state.selectedMail;if(!m)return;const att=state.mailAttachments.find(a=>a.id===id);try{toast('Téléchargement en cours…');const r=await invoke(CONFIG.mailFunction,{action:'attachment',mailbox:state.mailbox,message_id:m.id,attachment_id:id});const a=r.attachment;if(!a?.contentBytes)throw Error('Cette pièce jointe ne peut pas être téléchargée avec ce service');const bytes=Uint8Array.from(atob(a.contentBytes),x=>x.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:a.contentType||'application/octet-stream'}));const link=document.createElement('a');link.href=url;link.download=a.name||att?.name||'document';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}catch(e){toast('Pièce jointe indisponible : '+msg(e))}}
async function loadMailFolders(){try{const r=await invoke(CONFIG.mailFunction,{action:'folders',mailbox:state.mailbox});state.mailFolders=r.folders||[]}catch(e){toast('Dossiers : '+msg(e))}}
async function showMailFolders(){await loadMailFolders();modal('Dossiers Outlook',`<div class="stack">${[['inbox','Réception'],['sent','Envoyés'],['draft','Brouillons'],['archive','Archives'],['trash','Corbeille'],...state.mailFolders.filter(x=>!x.isHidden).map(x=>[x.id,x.displayName])].map(([id,name])=>`<button class="mail-folder-choice" data-folder-choice="${safe(id)}">📁 ${safe(name)}</button>`).join('')}</div>`,el=>el.querySelectorAll('[data-folder-choice]').forEach(b=>b.onclick=()=>{state.mailFolder=b.dataset.folderChoice;state.mailQuery='';closeModal();loadMails()}))}

async function invoke(name,body){const {data,error}=await state.db.functions.invoke(name,{body});if(error){let detail=error.message;try{if(error.context?.json){const j=await error.context.json();detail=j?.error||j?.message||detail}}catch{}throw Error(detail)}if(data?.error)throw Error(data.error);return data}
async function loadMailboxes(){state.mailError='';try{const r=await invoke(CONFIG.mailFunction,{action:'mailboxes'});state.mailboxes=(r.mailboxes||[]).filter(x=>x.email);state.mailbox=state.mailboxes.find(x=>x.email?.toLowerCase()===state.user.email?.toLowerCase())?.email||state.mailboxes[0]?.email||'';if(state.mailbox)await loadMails();else state.mailError='Aucune boîte Microsoft 365 autorisée'}catch(e){state.mailError=msg(e);if(state.page==='mails')render();toast('Microsoft 365 : '+msg(e))}}
async function loadMails(more=false){if(!state.mailbox)return;const seq=++state.mailListSeq;state.mailLoading=true;state.mailError='';if(!more){state.mails=[];state.mailNext=null}if(state.page==='mails'&&!state.view)render();try{let body={mailbox:state.mailbox,folder:state.mailFolder,top:40};if(more){if(!state.mailNext)return;body.action=(state.mailQuery||state.mailFilter==='unread')?'results_page':'messages_page';body.next_link=state.mailNext}else if(state.mailQuery){body.action='search_messages';body.query=state.mailQuery}else if(state.mailFilter==='unread'){body.action='unread_messages'}else{body.action='messages'}const r=await invoke(CONFIG.mailFunction,body);if(seq!==state.mailListSeq)return;const newRows=r.messages||[];const ids=new Set(state.mails.map(x=>x.id));state.mails=more?[...state.mails,...newRows.filter(m=>!ids.has(m.id))]:newRows;state.mailNext=r.next_link||null}catch(e){if(seq===state.mailListSeq)state.mailError=msg(e)}finally{if(seq===state.mailListSeq){state.mailLoading=false;if(state.page==='mails'&&!state.view)render()}}}
async function mailDetail(i){const m=state.mails[i];if(!m)return;state.selectedMail=m;state.mailAttachments=[];state.view='mail';render();try{const r=await invoke(CONFIG.mailFunction,{action:'message',mailbox:state.mailbox,message_id:m.id});if(state.selectedMail?.id!==m.id)return;state.selectedMail={...m,...(r.message||{})};state.mailAttachments=r.attachments||[];if(!state.selectedMail.isRead){await invoke(CONFIG.mailFunction,{action:'mark_read',mailbox:state.mailbox,message_id:m.id,is_read:true});state.selectedMail.isRead=true;m.isRead=true}render()}catch(e){toast('Détail Microsoft 365 : '+msg(e))}}

async function loadCalendar(){state.calendarError='';try{const email=state.profile?.email||state.user.email;if(!email)return;const start=new Date();start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+3);const r=await invoke(CONFIG.calendarFunction,{action:'events',user_email:email,time_min:start.toISOString(),time_max:end.toISOString(),max_results:60});state.events=r.events||[]}catch(e){state.calendarError=msg(e)}if(state.page==='home')render()}
async function queryRows(table,limit=250){const {data,error}=await state.db.from(table).select('*').limit(limit);if(error)throw error;return data||[]}
async function loadTasks(){const {data,error}=await state.db.from('web_tasks_new').select('id,copro,copro_id,title,status,priority,is_urgent,due_date,assigned_to,history').order('id',{ascending:false}).limit(350);if(error)throw error;state.tasks=data||[]}
async function loadSinistres(){const {data,error}=await state.db.from('web_sinistres').select('*').order('id',{ascending:false}).limit(150);if(error)throw error;state.sinistres=data||[]}
async function loadBasics(){const [cp,assign]=await Promise.all([queryRows('web_copros',600),state.db.from('user_copros').select('copro_code,user_id').eq('user_id',state.user.id)]);if(assign.error)throw assign.error;const assignedCodes=new Set((assign.data||[]).map(x=>String(x.copro_code)));const profile=state.profile;const showAll=profile?.can_view_all_copros===true;state.copros=cp.filter(c=>c.active!==false).map(c=>({...c,profile:typeof c.profile==='string'?parseProfile(c.profile):c.profile||{}}));state.allowed=new Set(state.copros.filter(c=>showAll||assignedCodes.has(String(c.code))).map(c=>String(c.code)));if(!state.allowed.size)info('Aucune résidence affectée à ce compte. Contactez un administrateur.',true);if(state.context&&!state.copros.some(c=>c.name===state.context&&canSeeCopro(c)))resetContext()}
function parseProfile(value){try{return JSON.parse(value)||{}}catch{return {}}}
async function reloadAll(force=false){if(!state.db||!state.user)return;if(!force&&Date.now()-state.updated<20000)return;const errors=[];try{await loadBasics()}catch(e){errors.push('Copropriétés : '+msg(e));state.copros=[];state.allowed.clear()}
await Promise.allSettled([loadTasks().catch(e=>errors.push('Tâches : '+msg(e))),loadSinistres().catch(e=>errors.push('Sinistres : '+msg(e))),loadPocketNotes().catch(e=>errors.push('Notes : '+msg(e)))]);state.dataErrors=errors;state.updated=Date.now();if(errors.length)info('Modules non disponibles : '+errors.join(' ; '),true);else info('');render()}
async function loadPocketNotes(){const {data,error}=await state.db.from('web_pocket_notes').select('id,text,copro_name,created_at,status,user_id').eq('user_id',state.user.id).eq('status','inbox').order('created_at',{ascending:false}).limit(60);if(error)throw error;state.notes=data||[]}
async function initAuth(){if(!window.supabase?.createClient){$('login-message').textContent='Chargement de la bibliothèque Supabase impossible. Vérifiez la connexion Internet.';return}state.db=window.supabase.createClient(CONFIG.supabaseUrl,CONFIG.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});state.db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT')signedOut()});const {data,error}=await state.db.auth.getUser();if(!error&&data?.user)await signedIn(data.user)}
async function signedIn(user){state.user=user;const {data,error}=await state.db.from('user_profiles').select('*').eq('id',user.id).maybeSingle();if(error||!data||data.active===false){await state.db.auth.signOut();throw Error('Profil WAPILOT absent, inaccessible ou désactivé. Contactez un administrateur.')}state.profile=data;$('user-title').textContent=(data.full_name||data.email||user.email||'Utilisateur');$('account').textContent=(data.full_name||user.email||'U').slice(0,1).toUpperCase();$('screen-login').classList.add('hidden');$('app').classList.remove('hidden');refreshContext();render();await reloadAll(true);loadCalendar();}
function signedOut(){cameraStop();photoClear();state.user=null;state.profile=null;state.tasks=[];state.mails=[];state.copros=[];state.allowed.clear();state.events=[];$('app').classList.add('hidden');$('screen-login').classList.remove('hidden');closeModal();info('')}
async function login(e){e.preventDefault();if(!state.db)await initAuth();if(!state.db)return;const f=new FormData(e.currentTarget);$('btn-login').disabled=true;$('login-message').textContent='Connexion en cours…';try{const {data,error}=await state.db.auth.signInWithPassword({email:String(f.get('email')).trim(),password:String(f.get('password'))});if(error)throw error;await signedIn(data.user);$('login-message').textContent=''}catch(err){$('login-message').textContent='Connexion refusée : '+msg(err)}finally{$('btn-login').disabled=false}}
async function recover(){if(!state.db)return;const email=document.querySelector('#login-form [name=email]')?.value?.trim();if(!email)return toast('Indiquez d’abord votre adresse e-mail');try{const {error}=await state.db.auth.resetPasswordForEmail(email);if(error)throw error;toast('Demande envoyée. Suivez les instructions du mail.')}catch(e){toast('Réinitialisation : '+msg(e))}}
async function accountModal(){modal('Mon compte',`<div class="card pad"><b>${safe(state.profile.full_name||state.user.email)}</b><p class="sub">${safe(state.user.email)}<br>Rôle : ${safe(state.profile.role||'Utilisateur')}</p><p class="footer-note">La session utilise l'authentification Supabase déjà employée par WAPILOT.</p></div><div class="actions"><button class="secondary" id="account-refresh">Actualiser</button><button class="secondary danger" id="account-signout">Se déconnecter</button></div>`,()=>{$('account-refresh').onclick=async()=>{closeModal();await reloadAll(true);await Promise.allSettled([loadCalendar(),state.mailboxes.length?loadMails():Promise.resolve()]);toast('Actualisation terminée')};$('account-signout').onclick=async()=>{if(!confirm('Déconnecter WAPI POCKET ?'))return;await state.db.auth.signOut();signedOut()}})}
/* V2.1 : transmission immédiate au serveur WAPILOT. Pas de file locale de synchronisation. */
function cameraStop(){if(state.cameraStream){for(const t of state.cameraStream.getTracks())t.stop();state.cameraStream=null}}
function openCamera(){const fallback=()=>$('camera-input')?.click();if(!navigator.mediaDevices?.getUserMedia){fallback();return}navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}}}).then(stream=>{state.cameraStream=stream;modal('Prendre une photo',`<div class="camera-view"><video id="camera-video" autoplay playsinline muted></video><div class="actions"><button type="button" id="camera-cancel" class="secondary">Annuler</button><button type="button" class="primary" id="camera-shot">● Photographier</button></div></div>`,()=>{const v=$('camera-video');v.srcObject=stream;v.play().catch(()=>{});$('camera-cancel').onclick=()=>{cameraStop();closeModal()};$('camera-shot').onclick=async()=>{const video=$('camera-video');if(!video?.videoWidth)return toast('Caméra en cours de démarrage');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(async blob=>{if(!blob)return toast('Capture impossible');const photo=new File([blob],`terrain-${Date.now()}.jpg`,{type:'image/jpeg'});cameraStop();closeModal();await handlePhoto([photo])},'image/jpeg',.83)}})}).catch(()=>{cameraStop();modal('Appareil photo',`<p class="sub">L’appareil photo intégré n’est pas disponible ou son accès est refusé. Essayez la capture native du téléphone.</p><button class="primary wide" id="camera-native">Ouvrir l’appareil photo du téléphone</button>`,()=>{$('camera-native').onclick=()=>{closeModal();fallback()}})})}
function photoClear(){for(const url of state.capturePreviewUrls)URL.revokeObjectURL(url);state.capturePreviewUrls=[];state.captureFiles=[];state.pendingCapture=null}
async function handlePhoto(files){const additions=[...files].filter(x=>x.type.startsWith('image/')).slice(0,Math.max(0,8-state.captureFiles.length));for(const f of additions){if(f.size>12*1024*1024){toast(`${f.name} trop volumineux (maximum 12 Mo)`);continue}state.captureFiles.push(f);state.pendingCapture=null}previewPhotos();if(!additions.length)toast('Aucune photo ajoutée')}
function previewPhotos(){const root=$('photos-preview');if(!root)return;for(const u of state.capturePreviewUrls)URL.revokeObjectURL(u);state.capturePreviewUrls=[];root.innerHTML='';state.captureFiles.forEach((f,i)=>{const url=URL.createObjectURL(f);state.capturePreviewUrls.push(url);const wrap=document.createElement('div');wrap.className='photo-chip';const im=document.createElement('img');im.src=url;im.alt=f.name;const b=document.createElement('button');b.type='button';b.textContent='×';b.setAttribute('aria-label','Retirer cette photo');b.onclick=()=>{state.captureFiles.splice(i,1);state.pendingCapture=null;previewPhotos()};wrap.append(im,b);root.append(wrap)})}
async function photoPrepare(file){if(file.size<2*1024*1024||!/^image\/(jpeg|png|webp)/.test(file.type))return file;try{const img=await createImageBitmap(file);const factor=Math.min(1,1920/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*factor);canvas.height=Math.round(img.height*factor);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close?.();const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.8));return blob?new File([blob],file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'}):file}catch{return file}}
async function captureSave(){
 if(state.uploadBusy)return;
 const text=$('note-text')?.value?.trim()||'',code=$('note-copro')?.value||'';
 const c=state.copros.find(x=>x.code===code),files=[...state.captureFiles];
 if(!text&&!files.length)return toast('Ajoutez une remarque ou une photo');
 if(!navigator.onLine)return toast('Connexion requise. Rien n’a été envoyé : conservez cette page ouverte.');
 if(code&&(!c||!canSeeCopro(c)))return toast('Copropriété non autorisée');
 // Identifiant et chemins conservés en mémoire pendant les nouvelles tentatives,
 // mais aucune file de synchronisation locale n'est créée.
 const note=state.pendingCapture||{id:crypto.randomUUID(),photos:[]};state.pendingCapture=note;
 state.uploadBusy=true;
 const btn=$('save-note'),status=$('capture-status');
 if(btn){btn.disabled=true;btn.textContent='Transmission en cours…'}
 if(status)status.textContent='Connexion à WAPILOT et transfert des photos…';
 try{
   // L'écriture précédente peut avoir abouti côté serveur sans réponse HTTP reçue.
   const prior=await state.db.from('web_pocket_notes').select('id').eq('id',note.id).maybeSingle();
   if(prior.error)throw prior.error;
   if(prior.data){photoClear();await loadPocketNotes().catch(()=>{});toast('Cette capture est déjà enregistrée dans WAPILOT');render();return}
   for(let i=note.photos.length;i<files.length;i++){
     const f=await photoPrepare(files[i]);
     const ext=(f.type==='image/png'?'png':f.type==='image/webp'?'webp':f.type==='image/heic'?'heic':'jpg');
     const path=`pocket/${state.user.id}/${note.id}/${String(i+1).padStart(2,'0')}.${ext}`;
     const {error}=await state.db.storage.from('syndic-files').upload(path,f,{contentType:f.type||'image/jpeg',upsert:false});
     if(error){
       // En cas de timeout, tester si l'objet existe n'est pas toujours possible
       // avec les policies Storage : on n'efface jamais aveuglément un objet distant.
       throw Error(`Envoi photo ${i+1}/${files.length} non confirmé : ${msg(error)}`);
     }
     const {data}=state.db.storage.from('syndic-files').getPublicUrl(path);
     note.photos.push({path,url:data.publicUrl,name:files[i].name,mime:f.type});
     if(status)status.textContent=`Photo ${i+1}/${files.length} envoyée…`;
   }
   const record={id:note.id,user_id:state.user.id,author_name:state.profile.full_name||state.user.email,
     text:text||'Photo terrain',copro_name:c?.name||null,copro_code:c?.code||null,
     urgent:!!$('note-urgent')?.checked,status:'inbox',
     photo_path:note.photos[0]?.path||null,photo_url:note.photos[0]?.url||null,
     photo_name:note.photos[0]?.name||null,photos:note.photos};
   const {error}=await state.db.from('web_pocket_notes').insert(record);
   if(error)throw error;
   photoClear();toast('Enregistré et transmis à WAPILOT');
   await loadPocketNotes().catch(()=>{});render();
 }catch(e){
   let confirmed=false;
   try{const {data}=await state.db.from('web_pocket_notes').select('id').eq('id',note.id).maybeSingle();confirmed=!!data}catch{}
   if(confirmed){photoClear();await loadPocketNotes().catch(()=>{});toast('Enregistrement retrouvé dans WAPILOT');render()}
   else{
     // Rien n'est déclaré envoyé. Les originaux restent sélectionnés à l'écran.
     // Ne pas nettoyer le Storage ici : un timeout peut masquer un upload réussi.
     const message='Envoi non confirmé : '+msg(e)+'. Conservez cette page ouverte et réessayez.';
     if(status)status.textContent=message;toast(message);
   }
 }finally{state.uploadBusy=false;if(btn){btn.disabled=false;btn.textContent='Envoyer à WAPILOT'}}
}
/* Event delegation: navigation indépendante des rendus. */
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-go],[data-page],[data-task],[data-copro],[data-sinistre],[data-mail],[data-compose],[data-compose-to],[data-open-create],[data-local-note],[data-back],[data-copro-action],[data-filter],[data-module],[data-mail-action],[data-mail-folder],[data-mail-filter],[data-mail-attachment]');if(!el)return;
if(el.dataset.mailAction){await mailAction(el.dataset.mailAction);return}if(el.dataset.mailFolder){if(el.dataset.mailFolder==='folders')await showMailFolders();else{state.mailFolder=el.dataset.mailFolder;state.mailQuery='';await loadMails()}return}if(el.dataset.mailFilter){state.mailFilter=el.dataset.mailFilter;await loadMails();return}if(el.dataset.mailAttachment){await downloadMailAttachment(el.dataset.mailAttachment);return}if(el.dataset.page){nav(el.dataset.page);return}if(el.dataset.go){if(el.dataset.go==='sinistres'){state.view='sinistres';render()}else nav(el.dataset.go);return}
if(el.dataset.back){nav(el.dataset.back);return}if(el.dataset.filter){state.filter=el.dataset.filter;render();return}
if(el.dataset.openCreate){taskForm();return}if(el.dataset.task){const t=state.tasks.find(x=>String(x.id)===el.dataset.task);if(t&&allowedTask(t))openTask(t);return}
if(el.dataset.copro){const c=state.copros.find(x=>String(x.code)===el.dataset.copro);if(c&&canSeeCopro(c)){state.view='copro:'+c.code;render()}return}
if(el.dataset.module){await openCoproModule(el.dataset.module,el.dataset.code);return}
if(el.dataset.coproAction){const c=state.copros.find(x=>String(x.code)===el.dataset.code);if(!c||!canSeeCopro(c))return;state.context=c.name;refreshContext();if(el.dataset.coproAction==='sinistres'){state.page='copros';state.view='sinistres';render()}else nav(el.dataset.coproAction);return}
if(el.dataset.sinistre){const s=scopedSinistres().find(x=>String(x.id)===el.dataset.sinistre);if(s){state.view='sinistre:'+s.id;render()}return}
if(el.dataset.mail!==undefined){await mailDetail(Number(el.dataset.mail));return}if(el.dataset.compose!==undefined){if(!state.mailboxes.length)await loadMailboxes();composeForm();return}if(el.dataset.composeTo){composeForm(el.dataset.composeTo);return}
if(el.dataset.localNote)return;});
document.addEventListener('input',e=>{if(e.target.id==='note-text')state.pendingCapture=null;if(e.target.id==='copro-search'){const q=norm(e.target.value);$('copro-results').innerHTML=coproListHtml(state.copros.filter(c=>canSeeCopro(c)&&(!state.context||c.name===state.context)&&(!q||norm(c.name+' '+c.code+' '+(c.profile?.city||'')).includes(q))))}});
document.addEventListener('change',e=>{if(e.target.id==='note-copro'||e.target.id==='note-urgent')state.pendingCapture=null;if(e.target.id==='mailbox-select'){state.mailbox=e.target.value;state.mailFolder='inbox';state.mailQuery='';state.mailNext=null;loadMails()}});
document.addEventListener('click',e=>{if(e.target.id==='save-note')captureSave();if(e.target.id==='camera-btn')openCamera();if(e.target.id==='file-btn')$('file-input')?.click();if(e.target.id==='mail-reload')loadMails();if(e.target.id==='mail-more')loadMails(true);if(e.target.id==='mail-search-submit'){state.mailQuery=$('mail-search-input')?.value?.trim()||'';loadMails()}});
document.addEventListener('change',async e=>{if(e.target.id==='camera-input'||e.target.id==='file-input'){await handlePhoto(e.target.files);e.target.value=''}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='mail-search-input'){e.preventDefault();state.mailQuery=e.target.value.trim();loadMails()}});
window.addEventListener('online',()=>{if(state.user)toast('Connexion retrouvée. Actualisez vos données.')});window.addEventListener('offline',()=>{if(state.user)info('Hors ligne : les envois vers WAPILOT sont indisponibles. Aucun fichier ne sera présenté comme enregistré.',true)});
document.addEventListener('DOMContentLoaded',()=>{$('login-form').addEventListener('submit',login);$('btn-reset').onclick=recover;$('account').onclick=accountModal;$('sync').onclick=async()=>{await reloadAll(true);if(state.page==='mails'&&state.mailboxes.length)await loadMails();if(state.page==='home')await loadCalendar();toast('Actualisation terminée')};$('clear-context').onclick=resetContext;initAuth().catch(e=>{$('login-message').textContent='Initialisation impossible : '+msg(e)});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{})});
